let reads = 0;

const extras = {
  wave() { return "wave"; },
  get id() { reads += 1; return reads; },
};

class Host {
  greet() { return "hello"; }
}

Object.assign(Host.prototype, extras);

const keys = [];
for (const key in new Host()) keys.push(key);

console.log(keys.join(","));
console.log(new Host().id + new Host().id);
console.log(reads);
console.log(Host.prototype.wave === extras.wave);
